from app.store.db import connect

PENDING = "pending"
APPROVED = "approved"
REJECTED = "rejected"
REVERSED = "reversed"


class RefundError(Exception):
    pass


class ConflictError(RefundError):
    pass


class OrderNotFound(RefundError):
    pass


def _to_dict(row) -> dict:
    return {
        "tenant": row["tenant"],
        "refund_id": row["refund_id"],
        "order_id": row["order_id"],
        "amount_cents": row["amount_cents"],
        "reason": row["reason"],
        "status": row["status"],
    }


def get(tenant: str, refund_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _to_dict(row)


def register(tenant: str, refund_id: str, order_id: str, amount_cents: int, reason: str) -> tuple[dict, bool]:
    """登记退款单。返回(退款单, 是否新建)；业务身份重复时返回既有单据。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if existing is not None:
            conn.execute("COMMIT")
            return _to_dict(existing), False

        order = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            conn.execute("ROLLBACK")
            raise OrderNotFound("order not found")

        # 已批准未冲正 + 待审核的退款总额视为已占用额度，保证逐笔批准时不会超出已收。
        reserved = conn.execute(
            "SELECT COALESCE(SUM(CASE WHEN status IN ('pending','approved') THEN amount_cents ELSE 0 END),0) AS reserved "
            "FROM refunds WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()["reserved"]
        if reserved + amount_cents > order["paid_cents"]:
            conn.execute("ROLLBACK")
            raise ConflictError("refund amount exceeds paid amount")

        conn.execute(
            "INSERT INTO refunds(tenant, refund_id, order_id, amount_cents, reason, status) "
            "VALUES(?,?,?,?,?,'pending')",
            (tenant, refund_id, order_id, amount_cents, reason),
        )
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()
    return get(tenant, refund_id), True


def review(tenant: str, refund_id: str, approve: bool) -> dict | None:
    """审核退款单：同意则对订单生效，拒绝则关闭。重复审核返回原结果。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if row["status"] in (APPROVED, REJECTED):
            conn.execute("COMMIT")
            return _to_dict(row)
        if row["status"] == REVERSED:
            conn.execute("ROLLBACK")
            raise ConflictError("refund already reversed")

        if approve:
            order = conn.execute(
                "SELECT paid_cents FROM orders WHERE tenant=? AND order_id=?",
                (tenant, row["order_id"]),
            ).fetchone()
            net_approved = conn.execute(
                "SELECT COALESCE(SUM(amount_cents),0) AS total FROM refunds "
                "WHERE tenant=? AND order_id=? AND status='approved'",
                (tenant, row["order_id"]),
            ).fetchone()["total"]
            if order is None or net_approved + row["amount_cents"] > order["paid_cents"]:
                conn.execute("ROLLBACK")
                raise ConflictError("refund exceeds paid amount")
            conn.execute(
                "UPDATE refunds SET status='approved' WHERE tenant=? AND refund_id=?",
                (tenant, refund_id),
            )
        else:
            conn.execute(
                "UPDATE refunds SET status='rejected' WHERE tenant=? AND refund_id=?",
                (tenant, refund_id),
            )
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()
    return get(tenant, refund_id)


def reverse(tenant: str, refund_id: str) -> dict | None:
    """冲正已生效退款单：金额全额退回订单，单据置为已冲正。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT status FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if row["status"] == REVERSED:
            conn.execute("ROLLBACK")
            raise ConflictError("refund already reversed")
        if row["status"] != APPROVED:
            conn.execute("ROLLBACK")
            raise ConflictError("refund not effective")
        conn.execute(
            "UPDATE refunds SET status='reversed' WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        )
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()
    return get(tenant, refund_id)


def net_approved(tenant: str, order_id: str) -> int:
    """订单已批准且未冲正的退款总额，即已从已收金额中扣减的部分。"""
    conn = connect()
    try:
        return conn.execute(
            "SELECT COALESCE(SUM(amount_cents),0) AS total FROM refunds "
            "WHERE tenant=? AND order_id=? AND status='approved'",
            (tenant, order_id),
        ).fetchone()["total"]
    finally:
        conn.close()

